assignments.referenceSolution:
`ParamSpec` captures the wrapped function's parameters, so the decorated function keeps its static signature; `functools.wraps` separately preserves runtime metadata. The sleep functions are injected, so tests record the delay schedule instead of waiting. Exceptions that are not in `on` are not caught at all, so they propagate on the first attempt. Run the checker yourself with strict settings as part of this exercise.

**`retry.py`**

```python
from __future__ import annotations

import asyncio
import functools
from collections.abc import Awaitable, Callable

Sleep = Callable[[float], None]
ASleep = Callable[[float], Awaitable[None]]


def retry[**P, R](
    *,
    attempts: int,
    on: type[Exception] | tuple[type[Exception], ...] = ConnectionError,
    base_delay: float = 0.5,
    sleep: Sleep = lambda s: None,
) -> Callable[[Callable[P, R]], Callable[P, R]]:
    """Retry a sync callable; the decorated function keeps its exact signature."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorate(fn: Callable[P, R]) -> Callable[P, R]:
        @functools.wraps(fn)
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except on:
                    if attempt == attempts:
                        raise
                    sleep(base_delay * 2 ** (attempt - 1))
            raise AssertionError("unreachable")  # keeps the checker happy

        return wrapper

    return decorate


def aretry[**P, R](
    *,
    attempts: int,
    on: type[Exception] | tuple[type[Exception], ...] = ConnectionError,
    base_delay: float = 0.5,
    sleep: ASleep = asyncio.sleep,
) -> Callable[[Callable[P, Awaitable[R]]], Callable[P, Awaitable[R]]]:
    """Async twin of retry: wraps a coroutine function."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorate(fn: Callable[P, Awaitable[R]]) -> Callable[P, Awaitable[R]]:
        @functools.wraps(fn)
        async def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            for attempt in range(1, attempts + 1):
                try:
                    return await fn(*args, **kwargs)
                except on:
                    if attempt == attempts:
                        raise
                    await sleep(base_delay * 2 ** (attempt - 1))
            raise AssertionError("unreachable")

        return wrapper

    return decorate
```

**`test_retry.py`**

```python
import inspect
from typing import assert_type

import pytest

from retry import aretry, retry


def test_retries_then_succeeds_with_backoff_schedule() -> None:
    delays: list[float] = []
    calls = 0

    @retry(attempts=4, base_delay=1.0, sleep=delays.append)
    def fetch(url: str, *, timeout: float = 1.0) -> str:
        nonlocal calls
        calls += 1
        if calls < 3:
            raise ConnectionError("down")
        return f"ok:{url}:{timeout}"

    result = fetch("u", timeout=2.0)
    assert_type(result, str)  # static check only; a runtime no-op
    assert result == "ok:u:2.0"
    assert calls == 3
    assert delays == [1.0, 2.0]


def test_gives_up_and_reraises_last_error() -> None:
    @retry(attempts=2)
    def always_fails() -> None:
        raise ConnectionError("still down")

    with pytest.raises(ConnectionError, match="still down"):
        always_fails()


def test_other_exceptions_are_not_retried() -> None:
    calls = 0

    @retry(attempts=5)
    def bad_input(x: int) -> int:
        nonlocal calls
        calls += 1
        raise ValueError("bad")

    with pytest.raises(ValueError):
        bad_input(1)
    assert calls == 1


def test_signature_and_metadata_are_preserved() -> None:
    @retry(attempts=2)
    def complete(prompt: str, *, max_tokens: int = 256) -> str:
        """Call the model."""
        return prompt

    assert complete.__name__ == "complete"
    assert complete.__doc__ == "Call the model."
    assert str(inspect.signature(complete)) == "(prompt: str, *, max_tokens: int = 256) -> str"


def test_invalid_attempts_rejected() -> None:
    with pytest.raises(ValueError, match="attempts"):
        retry(attempts=0)


@pytest.mark.asyncio
async def test_async_retry_uses_injected_sleep() -> None:
    delays: list[float] = []
    calls = 0

    async def record(seconds: float) -> None:
        delays.append(seconds)

    @aretry(attempts=3, base_delay=0.5, sleep=record)
    async def embed(text: str) -> list[float]:
        nonlocal calls
        calls += 1
        if calls < 3:
            raise ConnectionError("blip")
        return [float(len(text))]

    assert await embed("abcd") == [4.0]
    assert delays == [0.5, 1.0]
```

Run `pytest -q` (needs `pytest` and `pytest-asyncio`), then `mypy --strict retry.py test_retry.py`.

The `Result` type is a union of two small immutable generics, `TypeIs` narrows both branches, and the tagged `TypedDict` union gives per-case narrowing from the `type` discriminator. The final `assert_never` makes the handler exhaustive for the checker and a hard failure at runtime. Confirm the strict run yourself, and temporarily add a fourth event to watch the `assert_never` line fail.

**`results.py`**

```python
from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from typing import Literal, TypedDict, TypeIs, assert_never


@dataclass(frozen=True, slots=True)
class Ok[T]:
    value: T


@dataclass(frozen=True, slots=True)
class Err[E]:
    error: E


type Result[T, E] = Ok[T] | Err[E]


def is_ok[T, E](r: Result[T, E]) -> TypeIs[Ok[T]]:
    return isinstance(r, Ok)


def map_result[T, U, E](r: Result[T, E], fn: Callable[[T], U]) -> Result[U, E]:
    match r:
        case Ok(value):
            return Ok(fn(value))
        case Err():
            return r


def unwrap_or[T, D](r: Result[T, object], default: D) -> T | D:
    return r.value if isinstance(r, Ok) else default


def parse_int(text: str) -> Result[int, str]:
    try:
        return Ok(int(text))
    except ValueError:
        return Err(f"not an int: {text!r}")


class TokenEvent(TypedDict):
    type: Literal["token"]
    text: str


class ToolEvent(TypedDict):
    type: Literal["tool_call"]
    name: str
    arguments: dict[str, object]


class DoneEvent(TypedDict):
    type: Literal["done"]
    finish_reason: str


type Event = TokenEvent | ToolEvent | DoneEvent


def describe(event: Event) -> str:
    if event["type"] == "token":
        return "token"
    elif event["type"] == "tool_call":
        return "tool"
    elif event["type"] == "done":
        return "done"
    else:
        assert_never(event)
```

**`test_results.py`**

```python
from typing import assert_type

import pytest

from results import (
    DoneEvent, Err, Event, Ok, Result, TokenEvent, ToolEvent,
    describe, is_ok, map_result, parse_int, unwrap_or,
)


def test_parse_int_ok_and_err() -> None:
    assert parse_int("42") == Ok(42)
    assert parse_int("x") == Err("not an int: 'x'")


def test_map_result_applies_only_on_ok() -> None:
    assert map_result(Ok(2), lambda n: n * 10) == Ok(20)
    failed: Result[int, str] = Err("boom")
    assert map_result(failed, lambda n: n * 10) == Err("boom")


def test_is_ok_narrows_for_the_checker() -> None:
    r = parse_int("7")
    if is_ok(r):
        assert_type(r, Ok[int])  # static only
        assert r.value == 7
    else:
        assert_type(r, Err[str])
        pytest.fail("expected Ok")


def test_unwrap_or_default_union() -> None:
    assert unwrap_or(parse_int("5"), 0) == 5
    assert unwrap_or(parse_int("x"), None) is None


def test_results_are_immutable_values() -> None:
    ok = Ok(1)
    with pytest.raises(AttributeError):
        ok.value = 2  # type: ignore[misc]
    assert {Ok(1), Ok(1)} == {Ok(1)}


@pytest.mark.parametrize(
    ("event", "expected"),
    [
        pytest.param(TokenEvent(type="token", text="hi"), "token", id="token"),
        pytest.param(ToolEvent(type="tool_call", name="search", arguments={}), "tool", id="tool"),
        pytest.param(DoneEvent(type="done", finish_reason="stop"), "done", id="done"),
    ],
)
def test_describe_covers_every_event(event: Event, expected: str) -> None:
    assert describe(event) == expected


def test_unknown_event_fails_loudly_at_runtime() -> None:
    bogus: Event = {"type": "heartbeat"}  # type: ignore[assignment]
    with pytest.raises(AssertionError, match="unreachable"):
        describe(bogus)
```

Run `pytest -q`, then `mypy --strict results.py test_results.py`.
